// Server-only. Mapwork on a topographic map drawn in the style of a South
// African 1:50 000 sheet (20 m contours, index contours every 100 m, rivers,
// roads, buildings, a trig beacon). The terrain is generated by code, so every
// height, distance and gradient answer is exact. The map is made up: it is not
// a real place and not a copy of any official sheet.

import { mk, pick, rnd, type GeometryQuestion } from '@/lib/testbuilder/geometry'

const N = 96, MAP = 480, CELL = MAP / N, PX_PER_CM = 60, OX = 20, OY = 20
const INTERVAL = 20
const comma = (n: number) => String(n).replace('.', ',')

function noise(seed: number) {
  const g = 9, v = Array.from({ length: (g + 1) * (g + 1) }, (_, i) => { const s = Math.sin(seed * 997 + i * 78.233) * 43758.5453; return s - Math.floor(s) })
  return (x: number, y: number) => {
    const fx = x * g, fy = y * g, ix = Math.min(g - 1, Math.floor(fx)), iy = Math.min(g - 1, Math.floor(fy)), tx = fx - ix, ty = fy - iy
    const sm = (t: number) => t * t * (3 - 2 * t), a = v[iy * (g + 1) + ix]!, b = v[iy * (g + 1) + ix + 1]!, c = v[(iy + 1) * (g + 1) + ix]!, d = v[(iy + 1) * (g + 1) + ix + 1]!
    return a + (b - a) * sm(tx) + (c - a) * sm(ty) + (a - b - c + d) * sm(tx) * sm(ty)
  }
}

interface Terrain { h: number[][]; min: number; max: number; peak: { x: number; y: number } }
function makeTerrain(): Terrain {
  const base = pick([980, 1120, 1240, 1380, 1460]), seed = Math.random() * 1000, nz = noise(seed)
  const hills = Array.from({ length: rnd(3, 4) }, () => ({ x: Math.random(), y: Math.random(), s: 0.16 + Math.random() * 0.14, a: 70 + Math.random() * 90 }))
  const h: number[][] = []
  let min = Infinity, max = -Infinity, peak = { x: 0, y: 0 }
  const tilt = (Math.random() - 0.5) * 120, dir = Math.random() * Math.PI * 2
  for (let j = 0; j <= N; j++) {
    h[j] = []
    for (let i = 0; i <= N; i++) {
      const x = i / N, y = j / N
      let z = base + tilt * (Math.cos(dir) * (x - 0.5) + Math.sin(dir) * (y - 0.5)) + 40 * nz(x, y)
      for (const k of hills) z += k.a * Math.exp(-(((x - k.x) ** 2 + (y - k.y) ** 2) / (2 * k.s * k.s)))
      h[j]![i] = z
      if (z < min) min = z
      if (z > max) { max = z; peak = { x: i, y: j } }
    }
  }
  return { h, min, max, peak }
}

type Seg = [number, number, number, number]
function contourSegs(t: Terrain, L: number): Seg[] {
  const out: Seg[] = [], h = t.h
  for (let j = 0; j < N; j++) for (let i = 0; i < N; i++) {
    const v = [h[j]![i]!, h[j]![i + 1]!, h[j + 1]![i + 1]!, h[j + 1]![i]!]
    const pts: [number, number][] = []
    const edge = (a: number, b: number, p: [number, number], q: [number, number]) => {
      if ((v[a]! < L) !== (v[b]! < L)) { const k = (L - v[a]!) / (v[b]! - v[a]!); pts.push([p[0] + (q[0] - p[0]) * k, p[1] + (q[1] - p[1]) * k]) }
    }
    edge(0, 1, [i, j], [i + 1, j]); edge(1, 2, [i + 1, j], [i + 1, j + 1]); edge(2, 3, [i + 1, j + 1], [i, j + 1]); edge(3, 0, [i, j + 1], [i, j])
    if (pts.length === 2) out.push([pts[0]![0] * CELL, pts[0]![1] * CELL, pts[1]![0] * CELL, pts[1]![1] * CELL])
    else if (pts.length === 4) { out.push([pts[0]![0] * CELL, pts[0]![1] * CELL, pts[1]![0] * CELL, pts[1]![1] * CELL], [pts[2]![0] * CELL, pts[2]![1] * CELL, pts[3]![0] * CELL, pts[3]![1] * CELL]) }
  }
  return out
}
const heightAt = (t: Terrain, x: number, y: number) => {
  const gx = Math.min(N - 0.001, Math.max(0, x / CELL)), gy = Math.min(N - 0.001, Math.max(0, y / CELL)), i = Math.floor(gx), j = Math.floor(gy), fx = gx - i, fy = gy - j, h = t.h
  return h[j]![i]! * (1 - fx) * (1 - fy) + h[j]![i + 1]! * fx * (1 - fy) + h[j + 1]![i]! * (1 - fx) * fy + h[j + 1]![i + 1]! * fx * fy
}

function riverPath(t: Terrain): [number, number][] {
  // start on high ground and follow the steepest way down to the edge of the map
  let best = { x: 0, y: 0, z: -Infinity }
  for (let k = 0; k < 60; k++) { const x = rnd(Math.floor(N * 0.25), Math.floor(N * 0.75)), y = rnd(Math.floor(N * 0.25), Math.floor(N * 0.75)), z = t.h[y]![x]!; if (z > best.z) best = { x, y, z } }
  const path: [number, number][] = [[best.x * CELL, best.y * CELL]]
  let x = best.x * CELL, y = best.y * CELL, px = 0, py = 0
  for (let s = 0; s < 400; s++) {
    const e = 3, gx = heightAt(t, x + e, y) - heightAt(t, x - e, y), gy = heightAt(t, x, y + e) - heightAt(t, x, y - e)
    const m = Math.hypot(gx, gy) || 1
    let dx = -gx / m, dy = -gy / m
    dx = dx * 0.7 + px * 0.3; dy = dy * 0.7 + py * 0.3
    const mm = Math.hypot(dx, dy) || 1; dx /= mm; dy /= mm
    x += dx * 5; y += dy * 5; px = dx; py = dy
    path.push([x, y])
    if (x < 0 || y < 0 || x > MAP || y > MAP) break
  }
  return path.map(([a, b]) => [Math.min(MAP, Math.max(0, a)), Math.min(MAP, Math.max(0, b))] as [number, number])
}

export function drawTopo(): { svg: string; t: Terrain; segs: Map<number, Seg[]> } {
  const t = makeTerrain(), segs = new Map<number, Seg[]>()
  const lo = Math.ceil(t.min / INTERVAL) * INTERVAL, hi = Math.floor(t.max / INTERVAL) * INTERVAL
  for (let L = lo; L <= hi; L += INTERVAL) segs.set(L, contourSegs(t, L))
  const body: string[] = []
  body.push(`<rect x="0" y="0" width="${MAP}" height="${MAP}" fill="#fbf8ef"/>`)
  // contours
  for (const [L, ss] of segs) {
    const idx = L % 100 === 0
    body.push(`<path d="${ss.map(s => `M${s[0].toFixed(1)} ${s[1].toFixed(1)}L${s[2].toFixed(1)} ${s[3].toFixed(1)}`).join('')}" fill="none" stroke="#b5702f" stroke-width="${idx ? 1.9 : 0.9}" stroke-linecap="round"/>`)
  }
  // river
  const rp = riverPath(t)
  body.push(`<polyline points="${rp.map(p => p.map(v => v.toFixed(1)).join(',')).join(' ')}" fill="none" stroke="#2f7fd1" stroke-width="2.2" stroke-linejoin="round"/>`)
  // road along low ground, left to right
  const road: [number, number][] = []
  for (let i = 0; i <= 24; i++) {
    const x = (i / 24) * MAP; let bestY = MAP / 2, bz = Infinity
    for (let y = 60; y < MAP - 60; y += 8) { const z = heightAt(t, x, y) + Math.abs(y - MAP / 2) * 0.05; if (z < bz) { bz = z; bestY = y } }
    road.push([x, bestY])
  }
  const sm = road.map((p, i) => { const a = road[Math.max(0, i - 1)]!, b = road[Math.min(road.length - 1, i + 1)]!; return [(a[0] + p[0] + b[0]) / 3, (a[1] + p[1] + b[1]) / 3] as [number, number] })
  const rd = sm.map(p => p.map(v => v.toFixed(1)).join(',')).join(' ')
  body.push(`<polyline points="${rd}" fill="none" stroke="#7a2a1a" stroke-width="4.2" stroke-linejoin="round"/><polyline points="${rd}" fill="none" stroke="#f0a58a" stroke-width="2.4" stroke-linejoin="round"/>`)
  for (let k = 0; k < 5; k++) { const p = sm[rnd(2, sm.length - 3)]!, off = (Math.random() < 0.5 ? -1 : 1) * rnd(9, 16); body.push(`<rect x="${(p[0] + rnd(-6, 6)).toFixed(1)}" y="${(p[1] + off).toFixed(1)}" width="6" height="6" fill="#222"/>`) }
  // trig beacon on the highest point
  const px = t.peak.x * CELL, py = t.peak.y * CELL
  body.push(`<polygon points="${px},${py - 7} ${px - 6},${py + 4} ${px + 6},${py + 4}" fill="none" stroke="#222" stroke-width="1.6"/><circle cx="${px}" cy="${py}" r="1.3" fill="#222"/>`)
  body.push(`<text x="${px + 9}" y="${py + 3}" font-family="Arial,Helvetica,sans-serif" font-size="10" font-weight="700" fill="#222">${comma(Math.round(t.max * 10) / 10)}</text>`)
  // index contour labels
  for (const [L, ss] of segs) {
    if (L % 100 !== 0 || ss.length < 12) continue
    const cand = ss.filter(s => s[0] > 40 && s[0] < MAP - 40 && s[1] > 30 && s[1] < MAP - 30 && Math.hypot(s[0] - px, s[1] - py) > 40)
    if (!cand.length) continue
    const s = cand[Math.floor(cand.length * (0.25 + Math.random() * 0.5))]!
    body.push(`<rect x="${(s[0] - 14).toFixed(1)}" y="${(s[1] - 6).toFixed(1)}" width="28" height="12" fill="#fbf8ef"/><text x="${s[0].toFixed(1)}" y="${(s[1] + 3.6).toFixed(1)}" text-anchor="middle" font-family="Arial,Helvetica,sans-serif" font-size="9.5" font-weight="700" fill="#7a4a14">${L}</text>`)
  }
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${MAP + OX * 2} ${MAP + OY * 2 + 36}" width="${MAP + OX * 2}" height="${MAP + OY * 2 + 36}"><rect width="100%" height="100%" fill="#fff"/><g transform="translate(${OX},${OY})">${body.join('')}</g>`
    + `<rect x="${OX}" y="${OY}" width="${MAP}" height="${MAP}" fill="none" stroke="#222" stroke-width="2"/>`
    + `<g font-family="Arial,Helvetica,sans-serif" font-size="12" fill="#222"><text x="${OX}" y="${OY + MAP + 24}">1 : 50 000 (1 cm = 500 m)</text><text x="${OX + MAP - 4}" y="${OY + MAP + 24}" text-anchor="end">Contour interval ${INTERVAL} m</text></g>`
    + `<g transform="translate(${OX + MAP - 20},${OY + 26})"><polygon points="0,-16 6,6 0,2 -6,6" fill="#222"/><text x="0" y="20" text-anchor="middle" font-family="Arial" font-size="12" font-weight="700" fill="#222">N</text></g></svg>`
  return { svg, t, segs }
}

type Pt = { x: number; y: number; h: number }
function pickOnContour(segs: Map<number, Seg[]>, level: number, avoid: { x: number; y: number }[], minFromEdge = 40): Pt | null {
  const ss = (segs.get(level) ?? []).filter(s => { const x = (s[0] + s[2]) / 2, y = (s[1] + s[3]) / 2; return x > minFromEdge && x < MAP - minFromEdge && y > minFromEdge && y < MAP - minFromEdge && avoid.every(a => Math.hypot(a.x - x, a.y - y) > 50) })
  if (!ss.length) return null
  const s = ss[Math.floor(Math.random() * ss.length)]!
  return { x: (s[0] + s[2]) / 2, y: (s[1] + s[3]) / 2, h: level }
}
function addPoints(svg: string, pts: { n: string; p: Pt }[]): string {
  const extra = pts.map(({ n, p }) => `<circle cx="${OX + p.x}" cy="${OY + p.y}" r="4.2" fill="#d62828" stroke="#fff" stroke-width="1.2"/><text x="${OX + p.x + 8}" y="${OY + p.y - 7}" font-family="Arial,Helvetica,sans-serif" font-size="15" font-weight="800" fill="#d62828" stroke="#fff" stroke-width="3" paint-order="stroke">${n}</text>`).join('')
  return svg.replace('</svg>', `${extra}</svg>`)
}

export const TOPO = [
  { id: 'topoHeights', use: 'Grades 10-12 geography mapwork: read heights from a 1:50 000 style topographic map by counting contour lines, and find the height difference.' },
  { id: 'topoGradient', use: 'Grades 10-12 geography mapwork: gradient (1 : n) between two points on a 1:50 000 style topographic map from heights and map distance.' },
  { id: 'topoDistance', use: 'Grades 10-12 geography mapwork: real distance in km and metres between two points from the map distance in cm on a 1:50 000 map.' },
]
export const TOPO_IDS = TOPO.map(t => t.id)

function twoPoints(kind: 'heights' | 'gradient' | 'distance'): { svg: string; a: Pt; b: Pt; cm: number } | null {
  for (let tries = 0; tries < 40; tries++) {
    const { svg, segs } = drawTopo()
    const levels = [...segs.keys()]
    const idxLevels = levels.filter(l => l % 100 === 0), other = levels.filter(l => l % 100 !== 0)
    if (!idxLevels.length || !other.length) continue
    const a = pickOnContour(segs, pick(idxLevels), [])
    if (!a) continue
    const b = pickOnContour(segs, pick(other), [a])
    if (!b) continue
    const px = Math.hypot(a.x - b.x, a.y - b.y)
    if (px < 150 || px > 330 || a.h === b.h) continue
    const cm = Math.round((px / PX_PER_CM) * 10) / 10
    return { svg: addPoints(svg, [{ n: 'A', p: a }, { n: 'B', p: b }]), a, b, cm }
  }
  return null
}

export function makeTopo(id: string): GeometryQuestion | null {
  const kind = id === 'topoHeights' ? 'heights' : id === 'topoGradient' ? 'gradient' : id === 'topoDistance' ? 'distance' : null
  if (!kind) return null
  const r = twoPoints(kind)
  if (!r) return null
  const { svg, a, b, cm } = r
  const vi = Math.abs(a.h - b.h), km = cm * 0.5, m = cm * 500
  const note = 'This map is made up for practice. The scale is 1 : 50 000 and the contour interval is 20 m. Contours with a number are index contours.'
  if (kind === 'heights') {
    return mk(`${note} Point A and point B each lie on a contour line. Give the height above sea level of A and of B, and the difference in height between them.`, svg,
      [{ id: 'a', label: 'Height of A =', unit: 'm' }, { id: 'b', label: 'Height of B =', unit: 'm' }, { id: 'd', label: 'Height difference =', unit: 'm' }], { a: a.h, b: b.h, d: vi }, [],
      `A is on the ${a.h} m index contour. Count the contours from a numbered one, each is ${INTERVAL} m, and B is on the ${b.h} m contour. The difference is ${Math.max(a.h, b.h)} − ${Math.min(a.h, b.h)} = ${vi} m.`)
  }
  if (kind === 'distance') {
    return mk(`${note} The straight-line distance from A to B on the map is ${comma(cm)} cm. Calculate the real distance in kilometres and in metres.`, svg,
      [{ id: 'km', label: 'Real distance =', unit: 'km' }, { id: 'm', label: 'Real distance =', unit: 'm' }], { km, m }, [],
      `1 cm on the map is 500 m (0,5 km). ${comma(cm)} cm × 0,5 = ${comma(km)} km. ${comma(cm)} cm × 500 = ${comma(m)} m.`, 0.01)
  }
  const gradient = Math.round(m / vi)
  return mk(`${note} Point A and point B each lie on a contour line. The distance from A to B on the map is ${comma(cm)} cm. Work out the vertical interval (VI), the horizontal equivalent (HE) in metres, and the gradient as 1 : n (round n to the nearest whole number).`, svg,
    [{ id: 'vi', label: 'VI =', unit: 'm' }, { id: 'he', label: 'HE =', unit: 'm' }, { id: 'g', label: 'Gradient 1 :' }], { vi, he: m, g: gradient }, [],
    `VI = ${Math.max(a.h, b.h)} − ${Math.min(a.h, b.h)} = ${vi} m. HE = ${comma(cm)} cm × 500 = ${comma(m)} m. Gradient = HE ÷ VI = ${comma(m)} ÷ ${vi} = 1 : ${gradient}.`, 1)
}
